CREATE TABLE "regimes"("regime_id" INTEGER PRIMARY KEY,"regime_tributario" TEXT);
CREATE TABLE "clientes"("cliente_id" INTEGER PRIMARY KEY,"codigo_cliente" TEXT,"regime_id" INTEGER,"setor" TEXT,"uf" TEXT,"status" TEXT,FOREIGN KEY("regime_id") REFERENCES "regimes"("regime_id"));
CREATE TABLE "responsaveis"("responsavel_id" INTEGER PRIMARY KEY,"codigo_responsavel" TEXT,"equipe" TEXT,"senioridade" TEXT);
CREATE TABLE "tipos_obrigacao"("tipo_obrigacao_id" INTEGER PRIMARY KEY,"obrigacao" TEXT,"periodicidade" TEXT);
CREATE TABLE "obrigacoes"("obrigacao_id" INTEGER PRIMARY KEY,"cliente_id" INTEGER,"tipo_obrigacao_id" INTEGER,"responsavel_id" INTEGER,"competencia" TEXT,"data_limite" TEXT,"data_entrega" TEXT,"status" TEXT,"no_prazo" INTEGER,FOREIGN KEY("cliente_id") REFERENCES "clientes"("cliente_id"),FOREIGN KEY("tipo_obrigacao_id") REFERENCES "tipos_obrigacao"("tipo_obrigacao_id"),FOREIGN KEY("responsavel_id") REFERENCES "responsaveis"("responsavel_id"));
CREATE TABLE "documentos"("documento_id" INTEGER PRIMARY KEY,"cliente_id" INTEGER,"competencia" TEXT,"tipo_documento" TEXT,"data_solicitacao" TEXT,"data_recebimento" TEXT,"status" TEXT,FOREIGN KEY("cliente_id") REFERENCES "clientes"("cliente_id"));
CREATE TABLE "impostos"("imposto_id" INTEGER PRIMARY KEY,"cliente_id" INTEGER,"competencia" TEXT,"tributo" TEXT,"valor_apurado" REAL,"data_vencimento" TEXT,FOREIGN KEY("cliente_id") REFERENCES "clientes"("cliente_id"));
CREATE TABLE "guias"("guia_id" INTEGER PRIMARY KEY,"imposto_id" INTEGER,"valor" REAL,"data_vencimento" TEXT,"data_pagamento" TEXT,"status" TEXT,FOREIGN KEY("imposto_id") REFERENCES "impostos"("imposto_id"));
CREATE TABLE "pendencias"("pendencia_id" INTEGER PRIMARY KEY,"cliente_id" INTEGER,"responsavel_id" INTEGER,"data_abertura" TEXT,"tipo" TEXT,"prioridade" TEXT,"status" TEXT,FOREIGN KEY("cliente_id") REFERENCES "clientes"("cliente_id"),FOREIGN KEY("responsavel_id") REFERENCES "responsaveis"("responsavel_id"));
CREATE TABLE "honorarios"("honorario_id" INTEGER PRIMARY KEY,"cliente_id" INTEGER,"competencia" TEXT,"valor" REAL,"data_vencimento" TEXT,"data_pagamento" TEXT,"status" TEXT,FOREIGN KEY("cliente_id") REFERENCES "clientes"("cliente_id"));